import{_ as s,o as a,c as t,a0 as n}from"./chunks/framework.F8L2D_2n.js";const u=JSON.parse('{"title":"Request List","description":"","frontmatter":{},"headers":[],"relativePath":"tui/request-list.md","filePath":"tui/request-list.md"}'),i={name:"tui/request-list.md"};function l(p,e,r,o,d,c){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="request-list" tabindex="-1">Request List <a class="header-anchor" href="#request-list" aria-label="Permalink to &quot;Request List&quot;">​</a></h1><p>The request list is the first screen you see. It displays all operations discovered from your OpenAPI files in a compact, filterable list alongside a preview panel.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p>The screen is split into two panels:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────┬─────────────────────────────┐</span></span>
<span class="line"><span>│  🔍 type / to filter..│  GET /pets                  │</span></span>
<span class="line"><span>│                       │  List all pets               │</span></span>
<span class="line"><span>│  ── pets (3) ──      │  Server: api.example.com     │</span></span>
<span class="line"><span>│  GET /pets            │                             │</span></span>
<span class="line"><span>│  POST /pets           │  [s] Send  [Ctrl+T] Tags    │</span></span>
<span class="line"><span>│  GET /pets/{id}       │  ────────────────────────── │</span></span>
<span class="line"><span>│                       │  Status: 200 OK              │</span></span>
<span class="line"><span>│  ── users (2) ──     │  --- Body ---                │</span></span>
<span class="line"><span>│  GET /users           │  { &quot;data&quot;: [...] }          │</span></span>
<span class="line"><span>│  POST /users          │                             │</span></span>
<span class="line"><span>├──────────────────────┴─────────────────────────────┤</span></span>
<span class="line"><span>│  3 of 12  •  pets                                  │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span></code></pre></div><ul><li><strong>Left panel (~35%)</strong> — Compact request browser grouped by tag</li><li><strong>Right panel (~65%)</strong> — Preview of selected request with send and response</li></ul><h2 id="grouping-by-tags" tabindex="-1">Grouping By Tags <a class="header-anchor" href="#grouping-by-tags" aria-label="Permalink to &quot;Grouping By Tags&quot;">​</a></h2><p>Operations are grouped by their OpenAPI <code>tags</code> field. The first tag determines the group. Items without tags appear under an <code>Untagged</code> group:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">paths</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  /pets</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">    get</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">      tags</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;"> [</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;">pets</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">]</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">      summary</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span><span style="--shiki-light:#40A02B;--shiki-dark:#A6E3A1;"> List all pets</span></span></code></pre></div><p>Each group header shows the tag name and item count: <code>── pets (3) ──</code>.</p><h2 id="items" tabindex="-1">Items <a class="header-anchor" href="#items" aria-label="Permalink to &quot;Items&quot;">​</a></h2><p>Each item renders on a single compact line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>GET  /pets    List all pets</span></span></code></pre></div><ul><li><strong>Method badge</strong> — color-coded (GET=blue, POST=green, DELETE=red, etc.)</li><li><strong>URI</strong> — the endpoint path</li><li><strong>Summary</strong> — from the OpenAPI <code>summary</code> field, shown dimmed</li><li><strong>Draft items</strong> — prefixed with <code>✎</code></li></ul><h2 id="preview-panel" tabindex="-1">Preview Panel <a class="header-anchor" href="#preview-panel" aria-label="Permalink to &quot;Preview Panel&quot;">​</a></h2><p>Select an item to see its preview on the right:</p><ul><li>Request method, URI, and summary</li><li>Server URL</li><li>Description (if present)</li><li>Keybinding hints</li></ul><p>Press <strong><code>s</code></strong> to send the request. The response appears inline:</p><ul><li>Status code (colored: 2xx green, 3xx yellow, 4xx/5xx red)</li><li>Response headers</li><li>Response body (JSON/YAML formatted, scrollable with PgUp/PgDown)</li></ul><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code>/<code>k</code>, <code>↓</code>/<code>j</code></td><td>Navigate items</td></tr><tr><td><code>Enter</code></td><td>Open selected in editor</td></tr><tr><td><code>s</code></td><td>Send selected request (response in preview)</td></tr><tr><td><code>Ctrl+T</code></td><td>Edit tags (overlay at cursor position)</td></tr><tr><td><code>/</code></td><td>Focus filter</td></tr><tr><td><code>Esc</code></td><td>Blur filter / clear filter text</td></tr><tr><td><code>Ctrl+N</code></td><td>Create a new draft request</td></tr><tr><td><code>d</code></td><td>Duplicate selected request</td></tr><tr><td><code>x</code></td><td>Delete selected request</td></tr><tr><td><code>q</code></td><td>Quit</td></tr><tr><td><code>?</code></td><td>Show full help</td></tr></tbody></table><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><p>Press <code>/</code> to focus the filter bar. Type to narrow items by method, path, summary, or tag name. <code>Esc</code> clears the filter and blurs.</p><p>While filtering, <code>↑</code>/<code>↓</code> still navigates through filtered results. <code>Enter</code> opens the selected item.</p><h2 id="tag-editing" tabindex="-1">Tag Editing <a class="header-anchor" href="#tag-editing" aria-label="Permalink to &quot;Tag Editing&quot;">​</a></h2><p>Press <code>Ctrl+T</code> on a selected item to open the tag editor overlay at the cursor position:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>┌─ Edit Tags ────────────────────────┐</span></span>
<span class="line"><span>│ [pets] ×  [users] ×                │</span></span>
<span class="line"><span>│                                    │</span></span>
<span class="line"><span>│ Add tag: [____________]            │</span></span>
<span class="line"><span>│                                    │</span></span>
<span class="line"><span>│ Tab: delete mode  Enter: save      │</span></span>
<span class="line"><span>│ Esc: cancel                        │</span></span>
<span class="line"><span>└────────────────────────────────────┘</span></span></code></pre></div><ul><li><strong>Tab</strong> — cycle through tags for deletion</li><li><strong>Enter</strong> on a tag — remove it</li><li><strong>Type</strong> in the input — add a new tag (Enter to confirm)</li><li><strong>Enter</strong> (with empty input or input blurred) — save and persist</li><li><strong>Esc</strong> — discard changes</li></ul><p>For spec-backed requests, tags are written directly to the OpenAPI file.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">TUI Overview</a></li><li><a href="./keyboard-shortcuts">Keyboard Shortcuts</a></li><li><a href="./request-editor">Request Editor</a></li></ul>`,31)])])}const g=s(i,[["render",l]]);export{u as __pageData,g as default};
